def verify(witness):
    N = int(witness['N'])
    SPOT = int(witness['spot_bound'])
    if N < 1000 or SPOT < 100 or SPOT > N:
        raise ValueError('witness constants out of range')

    phi = list(range(N + 1))
    for i in range(2, N + 1):
        if phi[i] == i:
            for j in range(i, N + 1, i):
                phi[j] -= phi[j] // i

    def isprime(n):
        if n < 2:
            return False
        d = 2
        while d * d <= n:
            if n % d == 0:
                return False
            d += 1
        return True

    # CHECK 1: sieve sanity, exact integers: 1 <= phi[m] <= m-1 for all m >= 2
    for m in range(2, N + 1):
        if not (1 <= phi[m] <= m - 1):
            raise ValueError('phi sieve bounds violated at m=%d' % m)

    # CHECK 2: exhaustive modular check for small odd primes: no m < p with (p-1)|phi(m)
    small_count = 0
    for p in range(3, SPOT + 1):
        if isprime(p):
            small_count += 1
            for m in range(2, p):
                if phi[m] % (p - 1) == 0:
                    raise ValueError('small-prime derivation failed at p=%d, m=%d' % (p, m))
    if small_count < 100:
        raise ValueError('too few small primes checked')

    # CHECK 3: for every odd prime p <= N: phi(p) == p-1, so p witnesses m_{p-1} = p
    odd_count = 0
    for p in range(3, N + 1):
        if isprime(p):
            odd_count += 1
            if phi[p] != p - 1:
                raise ValueError('phi(p) != p-1 at p=%d' % p)
    if odd_count < 70000:
        raise ValueError('too few primes checked')

    # CHECK 4: q=2 endpoint honestly verified as the recorded exception: m_1 = 1 != 2
    if phi[1] != 1:
        raise ValueError('q=2 endpoint record wrong')

    return True
